# dump the mesh generated by echo5's init (0x11807c): vertices [0x261450] x [0x26145c], polygons [0x261454] x [0x261458]
import sys,os,struct
sys.path.insert(0,os.path.join(os.path.dirname(os.path.abspath(__file__)),'..'))
from harness import *
s=alloc(256); wr(s,b'0.5*Frame\0')
buf=alloc(320*240); desc=alloc(0x40); wr32(desc+0x10,320); wr32(desc+0x14,240); wr32(desc+0x18,8); wr32(desc+0x20,buf)
ev=alloc(0x100); wr32(ev+0x40,desc)
st=call(0x11807c,eax=s,edx=ev)
nv=rd32(0x26145c); npoly=rd32(0x261458); print('verts',nv,'polys',npoly)
vp=rd32(0x261450); wp=rd32(0x261464); pp=rd32(0x261454)
print('V0',hex(vp),hex(wp),hex(pp))
open(sys.argv[1]+'/e5_v.bin','wb').write(rd(vp,nv*0x34)); open(sys.argv[1]+'/e5_p.bin','wb').write(rd(pp,npoly*0x3c))
for i in range(6): print(struct.unpack('<13f',rd(vp+i*0x34,0x34)))
for i in range(4): print([hex(x) for x in struct.unpack('<15I',rd(pp+i*0x3c,0x3c))], struct.unpack('<4f',rd(pp+i*0x3c+0x1c,16)))
open(sys.argv[1]+'/e5_w.bin','wb').write(rd(wp,nv*0x34))
for q in (0,1,2,31,32):
    for k in range(4): print(q,k,[round(x,4) for x in struct.unpack('<13f',rd(wp+(q*4+k)*0x34,0x34))])
print('globals', [hex(rd32(a)) for a in (0x261450,0x261454,0x261458,0x26145c,0x261460,0x261464,0x261468,0x26146c,0x261470,0x1bde24,0x1bde1c,0x1bde20)])
print(rdf(0x1bde1c),rdf(0x1bde20),rdf(0x1bde24),rdf(0x261470))
